/// <summary>
/// Extension of formDataSource PurchLine in form PurchLineOpenOrder
/// </summary>
[ExtensionOf(formDataSourceStr(PurchLineOpenOrder, PurchLine))]
final class AVAPurchLineOpenOrderFrm_PurchLine_Extension
{
    public QueryBuildRange qbrAVAPurchRemainPercentage;

}

Method.Source:
/// <summary>
/// init method
/// </summary>
public void init()
{
    next init();

    // Add a filter to the query. Specify the field to use in the filter.
    qbrAVAPurchRemainPercentage = this.query().dataSourceTable(tableNum(PurchLine)).addRange(fieldNum(PurchLine, AVAPurchRemainPercentage));
}

/// <summary>
/// executeQuery method
/// </summary>
public void executeQuery()
{
    FormRealControl locFormRealControl;

    locFormRealControl  = element.design().controlName('AVAPurchRemainPercentageFilter');

    // Get the filter value from the filter control.
    qbrAVAPurchRemainPercentage.value(SysQuery::range('', locFormRealControl.realValue()));
    qbrAVAPurchRemainPercentage.enabled(true);

    next executeQuery();
}
